import React, { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";

// Fake data gói premium
const plans = [
  {
    id: "starter",
    name: "Starter",
    price: 0,
    desc: "Dành cho người mới",
  },
  {
    id: "core",
    name: "Core",
    price: 3360000,
    desc: "Dành cho cá nhân",
  },
  {
    id: "grow",
    name: "Grow",
    price: 1800000,
    desc: "Dành cho doanh nghiệp",
  },
  {
    id: "max",
    name: "Max",
    price: 1440000,
    desc: "Gói cao cấp",
  },
];

// Fake durations
const durations = [
  { id: "1m", label: "1 tháng", factor: 1 },
  { id: "12m", label: "12 tháng", factor: 12 },
];

// Main component
export default function Payment() {
  const [step, setStep] = useState(1);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [duration, setDuration] = useState("12m");
  const [paymentMethod, setPaymentMethod] = useState("vnpay");

  const handleNext = () => setStep((s) => s + 1);
  const handleBack = () => setStep((s) => s - 1);

  const total = selectedPlan
    ? plans.find((p) => p.id === selectedPlan).price *
      durations.find((d) => d.id === duration).factor
    : 0;

  return (
    <div className="w-full max-w-4xl mx-auto p-6">
      <Card className="p-6 shadow-xl rounded-2xl">
        {/* Step header */}
        <div className="mb-4 flex justify-between items-center">
          <h2 className="text-xl font-bold">
            {step === 1 && "Chọn gói Premium"}
            {step === 2 && "Chọn thời hạn"}
            {step === 3 && "Phương thức thanh toán"}
            {step === 4 && "Xác nhận thanh toán"}
            {step === 5 && "Hoàn tất"}
          </h2>
          <span className="text-sm text-gray-500">Bước {step}/5</span>
        </div>

        {/* Step content */}
        <CardContent>
          {step === 1 && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {plans.map((plan) => (
                <div
                  key={plan.id}
                  className={`p-4 border rounded-xl cursor-pointer ${
                    selectedPlan === plan.id ? "border-blue-500 bg-blue-50" : ""
                  }`}
                  onClick={() => setSelectedPlan(plan.id)}
                >
                  <h3 className="font-semibold">{plan.name}</h3>
                  <p className="text-sm">{plan.desc}</p>
                  <p className="mt-2 font-bold">
                    {plan.price === 0
                      ? "Miễn phí"
                      : plan.price.toLocaleString("vi-VN") + "đ / năm"}
                  </p>
                </div>
              ))}
            </div>
          )}

          {step === 2 && (
            <div className="flex gap-4">
              {durations.map((d) => (
                <Button
                  key={d.id}
                  variant={duration === d.id ? "default" : "outline"}
                  onClick={() => setDuration(d.id)}
                >
                  {d.label}
                </Button>
              ))}
            </div>
          )}

          {step === 3 && (
            <Tabs value={paymentMethod} onValueChange={setPaymentMethod}>
              <TabsList>
                <TabsTrigger value="vnpay">VNPay</TabsTrigger>
                <TabsTrigger value="bank">Chuyển khoản</TabsTrigger>
              </TabsList>
              <TabsContent value="vnpay" className="mt-4">
                <p>Quét mã QR để thanh toán bằng VNPay</p>
                <img
                  src="https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=VNPayFake"
                  alt="QR VNPay"
                  className="mt-4 mx-auto"
                />
              </TabsContent>
              <TabsContent value="bank" className="mt-4">
                <p>Chuyển khoản vào tài khoản sau:</p>
                <ul className="mt-2 text-sm">
                  <li><strong>Ngân hàng:</strong> Vietcombank</li>
                  <li><strong>Số TK:</strong> 123456789</li>
                  <li><strong>Chủ TK:</strong> Công ty Iconic</li>
                  <li><strong>Nội dung:</strong> user123 - {selectedPlan}</li>
                </ul>
              </TabsContent>
            </Tabs>
          )}

          {step === 4 && (
            <div>
              <h3 className="font-semibold mb-2">Thông tin đơn hàng</h3>
              <p>Gói: {selectedPlan}</p>
              <p>Thời hạn: {duration}</p>
              <p>Phương thức: {paymentMethod}</p>
              <p className="font-bold mt-2">
                Tổng tiền: {total.toLocaleString("vi-VN")}đ
              </p>
            </div>
          )}

          {step === 5 && (
            <div className="text-center">
              <h3 className="text-xl font-bold text-green-600">
                Thanh toán thành công!
              </h3>
              <p className="mt-2">Cảm ơn bạn đã nâng cấp Premium 🎉</p>
            </div>
          )}
        </CardContent>

        {/* Step actions */}
        <div className="mt-6 flex justify-between">
          {step > 1 && step < 5 && (
            <Button variant="outline" onClick={handleBack}>
              Quay lại
            </Button>
          )}
          {step < 5 && (
            <Button
              onClick={handleNext}
              disabled={step === 1 && !selectedPlan}
            >
              Tiếp tục
            </Button>
          )}
        </div>
      </Card>
    </div>
  );
}
